def sim(I):
    H,W=len(I),len(I[0])
    src=[(r,c) for r in range(H) for c in range(W) if I[r][c]==2][0]
    O=[row[:] for row in I]; dirs=[(1,1),(1,-1)]
    for dr,dc in dirs:
